            if (logged.isPresent()) {
                return logged.get();
            }
            SerialBatchRepository.SerialBatchRow serialParent = serialRepo
                    .findSerialBatch(parentKey)
                    .orElseThrow(() -> ApiException.unprocessable(
                            "普通批次不能使用受控拆批入口，请使用按数量拆批入口: " + parentKey));
