                .stream()
                .map(r -> new SerialIntervals.Interval(r.intervalStart(), r.intervalEnd()))
                .toList();
        List<SerialIntervals.Interval> union = new ArrayList<>();
        for (List<SerialIntervals.Interval> intervals : childIntervals) {
            union.addAll(intervals);
