                            interval.start(), interval.end(), now);
                }
                SerialBatchResponse body = new SerialBatchResponse(req.batchKey(),
                        req.productCode(), req.batchNo(), req.producedAt(),
                        BatchStatus.QUARANTINED, quantity, toViews(intervals), items, 1,
                        Instant.parse(now));
