                List.of(child(childA, new long[][]{{1, 4}}),
                        child(childB, new long[][]{{5, 10}})), 201);

        // 祖先（已 SPLIT 的根）召回 → 后代序号查询 recalled=true，recalledBy 为根
        recall(parent, "qa-lead", "根批召回", "CK-QR-" + unique(), 201);
        assertLeaf("PROD-QR", 3, childA, true, parent);
