        releaseBatch(parent2, "insp-2");
        recall(parent2, "qa", "叶批召回", "CK-QR2-" + unique(), 201);
        assertLeaf("PROD-QR2", 2, parent2, true, parent2);
        // 无关产品不受影响
        assertLeaf("PROD-QR", 3, childA, true, parent);
