/**
 * 指纹内列表元素分隔符（SOH 控制字符）：业务参数不可能包含该字符，避免列表拼接碰撞。
 */
private static final String LIST_SEP = ""; //"";

private static final int IDEMPOTENCY_MAX_ATTEMPTS = 3;
